('a0000000-0000-4000-8000-000000000001', 'Arogya Seva District Hospital', 'hospital', 'government', 'Near Jaistambh Chowk, Station Road', 'Raipur', 'Raipur', '492001', 21.2560, 81.6290, '0771-000-0101', '0771-000-0199', '{emergency,ambulance,icu,laboratory,xray,ultrasound,pharmacy,maternity,blood_bank,surgery,opd,child_care,vaccination}', true, '00:00', '23:59', '{0,1,2,3,4,5,6}', 300, 'Large government hospital with 24-hour emergency, operation theatre, blood bank and specialist OPDs. Free treatment under government schemes.'),
('a0000000-0000-4000-8000-000000000002', 'Navjeevan Primary Health Centre', 'phc', 'government', 'Ward 4, Near Gram Panchayat Bhawan', 'Abhanpur', 'Raipur', '493661', 21.0520, 81.7480, '0771-000-0201', '', '{opd,vaccination,maternity,pharmacy,laboratory}', false, '09:00', '16:00', '{1,2,3,4,5,6}', 6, 'Village health centre for check-ups, fever, BP and sugar tests, pregnancy care and vaccination. Medicines are free.'),
